jobs:[{id:'j1',title:'資深產品設計師',company:'禾光科技',location:'台北',skills:'Figma,UX',salary:140,slots:2,status:'招募中',notes:'打造下一代企業協作產品。'}, {id:'j2',title:'全端工程師',company:'方舟數位',location:'新竹',skills:'React,Node.js',salary:170,slots:3,status:'招募中',notes:'混合辦公，每週進辦公室兩天。'}, {id:'j3',title:'成長行銷經理',company:'日常生活',location:'台北',skills:'SEO,Growth',salary:150,slots:1,status:'招募中',notes:''}, {id:'j4',title:'資料工程師',company:'禾光科技',location:'台中',skills:'Python,SQL',salary:150,slots:1,status:'暫停',notes:''}],
