const text=(x,n=2000)=>typeof x==='string'&&x.length<=n;
const date=x=>/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(Date.parse(x))&&new Date(x).toISOString().slice(0,10)===x;
export function validate(s){if(!s||s.version!==1)throw Error('不支援的備份版本');for(const key of ['talents','jobs','referrals','activities'])if(!Array.isArray(s[key])||s[key].length>10000)throw Error('資料格式或筆數不正確');
for(const key of ['talents','jobs','referrals']){const ids=new Set();for(const x of s[key]){if(!x||!text(x.id,100)||!x.id||ids.has(x.id))throw Error('編號重複或無效');ids.add(x.id);if(!text(x.notes))throw Error('備註無效');}}
for(const t of s.talents)if(!text(t.name,100)||!t.name.trim()||!text(t.title,150)||!text(t.email,200)||!/^\S+@\S+\.\S+$/.test(t.email)||!text(t.location,100)||!text(t.skills,500)||!Number.isInteger(t.years)||t.years<0||t.years>60||!Number.isFinite(t.salary)||t.salary<0||!['開放機會','積極求職','暫不考慮'].includes(t.status))throw Error('人才資料無效');
for(const j of s.jobs)if(!text(j.title,150)||!j.title.trim()||!text(j.company,150)||!j.company.trim()||!text(j.location,100)||!text(j.skills,500)||!Number.isFinite(j.salary)||j.salary<0||!Number.isInteger(j.slots)||j.slots<1||j.slots>10000||!['招募中','暫停','已結案'].includes(j.status))throw Error('職缺資料無效');
const pairs=new Set();for(const r of s.referrals){const pair=r.talentId+'|'+r.jobId;if(!s.talents.some(t=>t.id===r.talentId)||!s.jobs.some(j=>j.id===r.jobId)||pairs.has(pair)||!text(r.referrer,100)||!r.referrer.trim()||!stages.includes(r.stage)||!date(r.date)||!Number.isFinite(r.fee)||r.fee<0)throw Error('推薦資料無效、關聯不存在或重複推薦');pairs.add(pair);}
for(const a of s.activities)if(!a||!text(a.text,500)||!text(a.time,100)||isNaN(Date.parse(a.time)))throw Error('操作紀錄無效');return s;}
export function match(t,j){const skills=j.skills.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);const own=t.skills.split(',').map(s=>s.trim().toLowerCase());return skills.length?Math.round(skills.filter(s=>own.includes(s)).length/skills.length*100):0;}
export function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');}
